class HelpPane final:public ui::Widget {
 const PixelFont& font_;const Skin& skin_;PixelScrollBar* bar_;int offset_=0,total_=0,hover_=-1,pressed_=-1;
public:
 struct Block {std::u32string text;int target=-1;bool heading=false;};
private:
 struct Row {Block block;std::vector<std::u32string> lines;int y=0,h=0;};std::vector<Block> blocks_;std::vector<Row> rows_;
 std::vector<std::u32string> wrap(const std::u32string& text,int width)const{std::vector<std::u32string> result;std::u32string line;for(auto ch:text){if(ch==U'\n'){result.push_back(line);line.clear();continue;}if(!line.empty()&&font_.measure(line+ch)>width){result.push_back(line);line.clear();}line+=ch;}if(!line.empty()||result.empty())result.push_back(line);return result;}
 int rowAt(gfx::Point p)const{const auto r=bounds();if(!r.contains(p)||p.x>=r.x2()-9*uiScale)return -1;const int y=(p.y-r.y)/uiScale+offset_;for(int i=0;i<int(rows_.size());++i)if(rows_[i].block.target>=0&&y>=rows_[i].y&&y<rows_[i].y+rows_[i].h)return i;return -1;}
 void scrollTo(int value){offset_=std::clamp(value,0,std::max(0,total_-bounds().h/uiScale));bar_->configure(total_,std::max(1,bounds().h/uiScale),offset_);invalidate();}
 void reflow(){rows_.clear();int y=3;const int width=std::max(1,bounds().w/uiScale-15);for(const auto& block:blocks_){Row row;row.block=block;row.lines=wrap(block.text,width);row.y=y;row.h=std::max(textControlHeight,int(row.lines.size())*12+6);y+=row.h+(block.target<0?UiSpacing::group:UiSpacing::related);rows_.push_back(std::move(row));}total_=y+3;const auto r=bounds();bar_->setBounds({r.x2()-7*uiScale,r.y,7*uiScale,r.h});bar_->setVisible(total_>r.h/uiScale);scrollTo(offset_);}
public:
 int active=-1;std::function<void(int)> selected;
 HelpPane(const PixelFont& f,const Skin& s):ui::Widget(ui::kGenericWidget),font_(f),skin_(s){setTransparent(true);setFocusStop(true);bar_=new PixelScrollBar(s,true);addChild(bar_);bar_->wheelStep=36;bar_->changed=[this](int v){scrollTo(v);};}
 void setBlocks(std::vector<Block> blocks,bool reset=true){blocks_=std::move(blocks);if(reset)offset_=0;reflow();}
 void setActive(int target){active=target;invalidate();}
 int scroll()const{return offset_;}
 void onResize(ui::ResizeEvent& ev)override{setBoundsQuietly(ev.bounds());reflow();}
 bool onProcessMessage(ui::Message* msg)override{if(msg->type()==ui::kMouseWheelMessage){scrollTo(offset_+static_cast<ui::MouseMessage*>(msg)->wheelDelta().y*36);return true;}if(auto m=dynamic_cast<ui::MouseMessage*>(msg)){if(msg->type()==ui::kMouseMoveMessage){hover_=rowAt(m->position());invalidate();}if(msg->type()==ui::kMouseLeaveMessage){hover_=-1;invalidate();}if(msg->type()==ui::kMouseDownMessage&&m->left()){requestFocus();pressed_=rowAt(m->position());if(pressed_>=0){captureMouse();return true;}}if(msg->type()==ui::kMouseUpMessage&&hasCapture()){releaseMouse();const int previous=pressed_;pressed_=-1;if(previous>=0&&previous==rowAt(m->position())&&selected)selected(rows_[previous].block.target);invalidate();return true;}}
 if(msg->type()==ui::kKeyDownMessage){const auto k=static_cast<ui::KeyMessage*>(msg);const auto code=k->scancode();if(code==ui::kKeyUp||code==ui::kKeyDown){std::vector<int> keys;for(const auto& row:rows_)if(row.block.target>=0)keys.push_back(row.block.target);if(!keys.empty()&&selected){auto at=std::find(keys.begin(),keys.end(),active);int n=at==keys.end()?0:int(at-keys.begin());n=std::clamp(n+(code==ui::kKeyUp?-1:1),0,int(keys.size())-1);selected(keys[n]);for(const auto& row:rows_)if(row.block.target==keys[n]){if(row.y<offset_)scrollTo(row.y);else if(row.y+row.h>offset_+bounds().h/uiScale)scrollTo(row.y+row.h-bounds().h/uiScale);break;}}else scrollTo(offset_+(code==ui::kKeyUp?-36:36));return true;}if(code==ui::kKeyPageUp||code==ui::kKeyPageDown){scrollTo(offset_+(code==ui::kKeyPageUp?-1:1)*bounds().h/uiScale);return true;}}
 if(msg->type()==ui::kFocusLeaveMessage){pressed_=-1;if(hasCapture())releaseMouse();}return ui::Widget::onProcessMessage(msg);}
 void onPaint(ui::PaintEvent& ev)override{auto& g=*ev.graphics();UiPaintScale scale(g);const auto r=uiLogical(clientBounds());skin_.draw(g,"panel_content",r);g.saveClip();g.clipRect({r.x+2,r.y+2,std::max(0,r.w-11),std::max(0,r.h-4)});for(int i=0;i<int(rows_.size());++i){const auto& row=rows_[i];const int y=r.y+row.y-offset_;if(y+row.h<r.y||y>=r.y2())continue;if(row.block.target>=0&&(row.block.target==active||i==hover_||i==pressed_))skin_.draw(g,row.block.target==active?"button.selected":i==pressed_?"button.pressed":"button.hover",{r.x+2,y,r.w-11,row.h});int yy=y+3;for(const auto& text:row.lines){font_.draw(g,text,r.x+4,yy,skin_[row.block.heading?"muted":"text"]);yy+=12;}}g.restoreClip();}
};

class HelpSearchEntry final:public PixelEntry {
 const PixelFont& font_;const Skin& skin_;std::u32string placeholder_;
public:HelpSearchEntry(const PixelFont& f,const Skin& s,std::u32string placeholder):PixelEntry(f,s),font_(f),skin_(s),placeholder_(std::move(placeholder)){}
 void onPaint(ui::PaintEvent& ev)override{PixelEntry::onPaint(ev);if(text().empty()&&!hasFocus()){auto& g=*ev.graphics();UiPaintScale scale(g);const auto r=uiLogical(clientBounds());g.saveClip();g.clipRect({r.x+3,r.y+2,std::max(0,r.w-6),std::max(0,r.h-4)});font_.draw(g,placeholder_,r.x+3,DialogLayout::centeredInkY(font_,placeholder_,r.y,r.h),skin_["muted"]);g.restoreClip();}}
};
class HelpDialog final:public PixelDialog {
 const PixelFont& font_;const Skin& skin_;bool tips_;int lang_;const std::vector<help::Article>& articles_;std::function<std::u32string(const std::string&)> binding_,label_;PixelEntry* search_;HelpPane *topics_,*article_;PixelButton *done_,*close_,*shortcuts_,*diagnostics_,*clear_;std::vector<int> matches_;std::string selected_;int action_=0;
 std::u32string text(const char32_t* zh,const char32_t* en)const{return lang_?en:zh;}
 std::u32string category(const std::string& id)const{if(id=="start")return tips_?text(U"修饰操作",U"Modifiers"):text(U"入门与保存",U"Getting started");if(id=="create")return tips_?text(U"快捷操作",U"Quick actions"):text(U"创作操作",U"Creating artwork");return tips_?text(U"特色功能",U"Features"):text(U"遇到问题",U"Troubleshooting");}
 bool matches(const help::Article& a,const std::u32string& query)const{std::u32string hay=a.title[lang_]+U" "+a.tip[lang_];for(const auto& step:a.steps)hay+=U" "+step[lang_];for(const auto& key:a.shortcuts)hay+=U" "+label_(key)+U" "+binding_(key);std::u32string word;auto found=[&]{if(word.empty())return true;const bool yes=historySearchMatches(hay,word);word.clear();return yes;};for(auto ch:query){if(ch==U' '||ch==U'\t'||ch==U'\n'||ch==U'\r'||ch==0x3000){if(!found())return false;}else word+=ch;}return found();}
 void showArticle(int index,bool remember=true){if(index<0||index>=int(articles_.size()))return;if(remember)selected_=articles_[index].id;topics_->setActive(index);const auto& a=articles_[index];std::vector<HelpPane::Block> rows{{category(a.category),-1,true},{a.title[lang_]}};for(int i=0;i<int(a.steps.size());++i)rows.push_back({unicodeText(std::to_string(i+1))+U". "+a.steps[i][lang_]});if(!a.tip[lang_].empty()){rows.push_back({text(U"操作提示",U"Tip"),-1,true});rows.push_back({a.tip[lang_]});}if(!a.shortcuts.empty()){rows.push_back({text(U"相关快捷键 · 当前设置",U"Related shortcuts · current settings"),-1,true});for(const auto& id:a.shortcuts){auto current=binding_(id);rows.push_back({label_(id)+U"  "+(current.empty()?text(U"未设置",U"Not assigned"):current)});}}article_->setBlocks(std::move(rows));}
public:
 HelpDialog(const PixelFont& font,const Skin& skin,const Skin& icons,bool tips,std::function<std::u32string(const std::string&)> binding,std::function<std::u32string(const std::string&)> label,bool diagnosticsEnabled=false,int language=0):PixelDialog(skin,"",ui::PopupWindow::ClickBehavior::CloseOnClickInOtherWindow),font_(font),skin_(skin),tips_(tips),lang_(language==0?0:1),articles_(tips?help::tipsArticles():help::helpArticles()),binding_(std::move(binding)),label_(std::move(label)),selected_(tips?"modifier-brushSizeAdjust":"first-art"){
 setAutoRemap(false);setWantFocus(true);setEnterBehavior(ui::PopupWindow::EnterBehavior::DoNothingOnEnter);search_=new HelpSearchEntry(font,skin,tips?text(U"例如：Shift、笔刷、补间、缩时",U"Try: Shift, brush, tween, timelapse"):text(U"例如：撤销、选区、导出、画不出来",U"Try: undo, selection, export, strokes"));addChild(search_);search_->Change.connect([this]{filter();});topics_=new HelpPane(font,skin);article_=new HelpPane(font,skin);addChild(topics_);addChild(article_);topics_->selected=[this](int i){showArticle(i);};auto button=[&](std::u32string title,std::function<void()> callback){auto b=new PixelButton(font,skin,std::move(title),std::move(callback));addChild(b);return b;};done_=button(text(U"关闭",U"Close"),[this]{closeWindow(nullptr);});close_=button(U"",[this]{closeWindow(nullptr);});close_->iconSkin=&icons;close_->icon="close";close_->skinStyle="icon_button";shortcuts_=button(text(U"快捷键设置",U"Shortcut settings"),[this]{action_=1;closeWindow(nullptr);});diagnostics_=button(text(U"打开诊断日志",U"Diagnostic logs"),[this]{action_=2;closeWindow(nullptr);});diagnostics_->setEnabled(diagnosticsEnabled);clear_=button(text(U"查看全部主题",U"Show all topics"),[this]{search_->setText("");filter();search_->requestFocus();});filter();}
 void focusSearch(){search_->requestFocus();}
 int requestedAction()const{return action_;}
 const std::vector<int>& results()const{return matches_;}
 const std::string& selectedId()const{return selected_;}
 void filter(){matches_.clear();const auto query=unicodeText(search_->text());for(int i=0;i<int(articles_.size());++i)if(matches(articles_[i],query))matches_.push_back(i);std::vector<HelpPane::Block> nav;for(const auto* categoryId:{"start","create","fix"}){bool header=false;for(int i:matches_)if(articles_[i].category==categoryId){if(!header){nav.push_back({category(categoryId),-1,true});header=true;}nav.push_back({articles_[i].title[lang_],i});}}topics_->setBlocks(std::move(nav));clear_->setVisible(matches_.empty());topics_->setVisible(!matches_.empty());if(matches_.empty())article_->setBlocks({{text(U"没有找到相关内容",U"No matching articles")},{text(U"试试更短的词，例如“保存”或“移动”，也可以清空搜索浏览全部主题。",U"Try a shorter term such as “save” or “move”, or clear the search to browse all topics.")}});else{int chosen=matches_.front();for(int i:matches_)if(articles_[i].id==selected_)chosen=i;showArticle(chosen,false);}invalidate();}
 void smokeQuery(const std::string& value){search_->setText(value);filter();}
 void smokeSelect(int index){topics_->selected(index);}
 bool diagnosticsEnabled()const{return diagnostics_->isEnabled();}
 void smokeShortcuts(){shortcuts_->Click();}
 void smokeDiagnostics(){diagnostics_->Click();}
 gfx::Size minimumDialogSize(int)const override{return {360*uiScale,340*uiScale};}
 void onResize(ui::ResizeEvent& ev)override{setBoundsQuietly(ev.bounds());const auto r=bounds();const int w=r.w/uiScale,h=r.h/uiScale;auto put=[&](ui::Widget* widget,gfx::Rect box){widget->setBounds(uiPhysical(box).offset(r.origin()));};layoutHeaderButton(close_);put(search_,{6,DialogLayout::bodyTop+12,w-12,textControlHeight});const int top=DialogLayout::bodyTop+38,bottom=DialogLayout::footer(h)-UiSpacing::group;const int available=std::max(1,bottom-top);if(w>=580){const int nav=std::min(220,(w-18)/3);put(topics_,{6,top,nav,available});put(article_,{6+nav+6,top,w-18-nav,available});}else{const int nav=std::max(60,available*28/100);put(topics_,{6,top,w-12,nav});put(article_,{6,top+nav+6,w-12,std::max(1,available-nav-6)});}const int footer=DialogLayout::footer(h);put(shortcuts_,{6,footer,100,textControlHeight});put(diagnostics_,{108,footer,100,textControlHeight});put(done_,{w-66,footer,60,textControlHeight});put(clear_,{6,bottom-22,w-12,textControlHeight});}
 void paintDialogContents(ui::PaintEvent& ev)override{auto& g=*ev.graphics();UiPaintScale scale(g);const auto r=uiLogical(clientBounds());drawDialogTitle(font_,g,r,tips_?text(U"使用技巧",U"Tips & tricks"):text(U"使用帮助",U"User guide"));font_.draw(g,tips_?text(U"搜索技巧",U"Search tips"):text(U"搜索帮助",U"Search help"),r.x+6,r.y+DialogLayout::bodyTop,skin_["text"]);const auto count=unicodeText(std::to_string(matches_.size()))+text(U" 篇",U" articles");font_.draw(g,count,r.x2()-6-font_.measure(count),r.y+DialogLayout::bodyTop,skin_["muted"]);}
 bool onProcessMessage(ui::Message* msg)override{if(processDialogGeometry(msg))return true;if(msg->type()==ui::kKeyDownMessage&&static_cast<ui::KeyMessage*>(msg)->scancode()==ui::kKeyEsc){closeWindow(nullptr);return true;}return PixelPopupWindow::onProcessMessage(msg);}
};
